obj=requests.get(url+'/api/tools/'+urllib.parse.quote(tid,safe=''), headers=headers, params={'io_details':'true'}, timeout=30).json()
print('name',obj.get('name'),'version',obj.get('version'))

def walk(inputs,path='',maxopts=8):
 for inp in inputs or []:
  name=inp.get('name'); typ=inp.get('type'); p=f'{path}.{name}' if path else name
  label=(inp.get('label') or '')[:80]
  print(p, typ, 'optional=',inp.get('optional'),'value=',inp.get('value'),'formats=',inp.get('extensions'),'label=',label)
  if typ=='select':
   opts=inp.get('options') or []
   print('  options sample', opts[:maxopts])
   hits=[o for o in opts if any(s in str(o[0]).lower()+str(o[1]).lower() for s in ['hg38','grch38','human','gcf_000001405.40'])]
   if hits[:20]: print('  human hits', hits[:20])
  if typ=='conditional':
   tp=inp.get('test_param',{})
   print('  test',tp.get('name'),tp.get('type'),tp.get('value'),tp.get('options'))
   for case in inp.get('cases',[]):
    print('  case',case.get('value'))
    walk(case.get('inputs'),p+'['+str(case.get('value'))+']',maxopts)
  if typ in ('repeat','section'):
   walk(inp.get('inputs'),p+'[]' if typ=='repeat' else p,maxopts)
walk(obj.get('inputs'))
print('\\noutputs')
for out in obj.get('outputs',[]): print(out.get('name'), out.get('format'), out.get('label'), out.get('from_work_dir'))
